"#include <metal_stdlib>\nusing namespace metal;\n"
"kernel void half_dev(device const uchar*codes[[buffer(0)]],device const half*cb[[buffer(1)]],device const float*x[[buffer(2)]],device float*out[[buffer(3)]],constant uint&blocks[[buffer(4)]],constant uint&tile[[buffer(5)]],threadgroup float*part[[threadgroup(0)]],uint tid[[thread_index_in_threadgroup]],ushort lane[[thread_index_in_simdgroup]],ushort sg[[simdgroup_index_in_threadgroup]],uint tg[[threadgroup_position_in_grid]]){uint row0=tg*tile;for(uint rr=0;rr<tile;rr++){uint row=row0+rr;float a=0;device const uchar*cr=codes+(ulong)row*blocks;for(uint b=tid;b<blocks;b+=256u){const device half*e=cb+uint(cr[b])*8u;device const float*xb=x+b*8u;for(uint d=0;d<8;d++)a+=float(e[d])*xb[d];}a=simd_sum(a);if(lane==0)part[rr*8u+sg]=a;}threadgroup_barrier(mem_flags::mem_threadgroup);if(tid==0){for(uint rr=0;rr<tile;rr++){float s=0;for(uint i=0;i<8;i++)s+=part[rr*8u+i];out[row0+rr]=s;}}}\n"
