static double run(id<MTLCommandQueue>q,id<MTLComputePipelineState>p,NSArray*bufs,uint blocks,uint K,uint rows,uint tile,float scale,int mode,int it){double best=1e9;for(int r=0;r<it;r++){id<MTLCommandBuffer>cb=[q commandBuffer];id<MTLComputeCommandEncoder>e=[cb computeCommandEncoder];[e setComputePipelineState:p];for(int i=0;i<4;i++)[e setBuffer:bufs[i] offset:0 atIndex:i];[e setBytes:&blocks length:4 atIndex:4];if(mode==0){[e setBytes:&tile length:4 atIndex:5];[e setThreadgroupMemoryLength:(NSUInteger)tile*8*4 atIndex:0];}else if(mode==1){[e setBytes:&tile length:4 atIndex:5];[e setBytes:&scale length:4 atIndex:6];[e setThreadgroupMemoryLength:(NSUInteger)tile*8*4 atIndex:0];}else{[e setBytes:&K length:4 atIndex:5];[e setBytes:&tile length:4 atIndex:6];[e setBytes:&scale length:4 atIndex:7];[e setThreadgroupMemoryLength:(NSUInteger)tile*8*4 atIndex:0];[e setThreadgroupMemoryLength:(NSUInteger)K*8 atIndex:1];}[e dispatchThreadgroups:MTLSizeMake((rows+tile-1)/tile,1,1) threadsPerThreadgroup:MTLSizeMake(256,1,1)];[e endEncoding];[cb commit];[cb waitUntilCompleted];double ms=(cb.GPUEndTime-cb.GPUStartTime)*1000.0;if(ms>0&&ms<best)best=ms;}return best;}
int main(){@autoreleasepool{id<MTLDevice>d=MTLCreateSystemDefaultDevice();id<MTLCommandQueue>q=[d newCommandQueue];NSError*err=nil;id<MTLLibrary>l=[d newLibraryWithSource:[NSString stringWithUTF8String:SRC] options:nil error:&err];if(!l){NSLog(@"%@",err);return 1;}id<MTLComputePipelineState>ph=[d newComputePipelineStateWithFunction:[l newFunctionWithName:@"half_dev"] error:&err],pg=[d newComputePipelineStateWithFunction:[l newFunctionWithName:@"i8_dev"] error:&err],pt=[d newComputePipelineStateWithFunction:[l newFunctionWithName:@"i8_tg"] error:&err];uint in_dim=7168,blocks=in_dim/8,rows=2048,K=2048;float scale=0.05f;id<MTLBuffer>codes=[d newBufferWithLength:(ulong)rows*blocks options:MTLResourceStorageModeShared];id<MTLBuffer>cbh=[d newBufferWithLength:(ulong)K*8*2 options:MTLResourceStorageModeShared];id<MTLBuffer>cbi=[d newBufferWithLength:(ulong)K*8 options:MTLResourceStorageModeShared];id<MTLBuffer>x=[d newBufferWithLength:(ulong)in_dim*4 options:MTLResourceStorageModeShared];id<MTLBuffer>out=[d newBufferWithLength:(ulong)rows*4 options:MTLResourceStorageModeShared];unsigned char*cp=codes.contents;for(ulong i=0;i<(ulong)rows*blocks;i++)cp[i]=rand()&0xFF;uint16_t*hp=cbh.contents;char*ip=cbi.contents;for(uint i=0;i<K*8;i++){int v=(rand()%255)-127;ip[i]=(char)v;__fp16 h=(__fp16)(scale*(float)v);hp[i]=*(uint16_t*)&h;}float*xp=x.contents;for(uint i=0;i<in_dim;i++)xp[i]=(rand()%100)/100.0f;NSArray*bh=@[codes,cbh,x,out];NSArray*bi=@[codes,cbi,x,out];printf("prequant int8 codebook bench in=%u rows=%u K=%u\n",in_dim,rows,K);uint tiles[]={1,4,8,16};for(int i=0;i<4;i++){uint tile=tiles[i];double h=run(q,ph,bh,blocks,K,rows,tile,scale,0,120);double gd=run(q,pg,bi,blocks,K,rows,tile,scale,1,120);double tg=run(q,pt,bi,blocks,K,rows,tile,scale,2,120);printf("tile=%2u half_dev=%.4f i8_dev=%.4f i8_tg=%.4f speed_i8dev=%.3fx speed_i8tg=%.3fx\n",tile,h,gd,tg,h/gd,h/tg);}return 0;}}
